import{_ as i,a0 as p,w as d,s as o,I as t,x as e,a1 as n,A as l,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Rust 基础系列 #6: 条件语句 | LCTT x X-CMD","titleTemplate":false,"description":"Rust 基础系列 #6: 条件语句 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Rust 基础系列 #6: 条件语句 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Rust 基础系列 #6: 条件语句 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230501.1 ⭐️⭐️ Rust Basics Series 6 Conditional Statements","title":"Rust 基础系列 #6: 条件语句","tag":"202306","desc":""},"relativePath":"202306/20230501.1 ⭐️⭐️ Rust Basics Series 6 Conditional Statements.md","filePath":"[post].md"}'),r={name:"202306/20230501.1 ⭐️⭐️ Rust Basics Series 6 Conditional Statements.md"};function g(h,s,b,f,u,k){const a=p("Link");return d(),o("div",null,[s[18]||(s[18]=t("h1",{id:"rust-基础系列-6-条件语句",tabindex:"-1"},[e("Rust 基础系列 #6: 条件语句 "),t("a",{class:"header-anchor",href:"#rust-基础系列-6-条件语句","aria-label":"Permalink to “Rust 基础系列 #6: 条件语句”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/11/094832bkkbs7oxntx7zxas.jpg",alt:""})],-1)),t("p",null,[s[1]||(s[1]=e("在 ",-1)),n(a,{href:"https://linux.cn/article-15855-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=e(" 中，你学习了函数。在这篇文章中，我们将学习使用条件语句来管理 Rust 程序的控制流。",-1))]),s[20]||(s[20]=c(`<h3 id="什么是条件语句" tabindex="-1">什么是条件语句？ <a class="header-anchor" href="#什么是条件语句" aria-label="Permalink to “什么是条件语句？”">​</a></h3><p>在编写代码的时候，最常见的任务之一就是检查某些条件是否为 <code>true</code> 或 <code>false</code>。“如果温度高于 35°C，打开空调。”</p><p>通过使用 <code>if</code> 和 <code>else</code> 这样的关键字（有时候结合使用），程序员可以根据条件（例如提供的参数数量、从命令行传递的选项、文件名、错误发生等）改变程序的行为。</p><p>所以，对一个程序员来说，了解任何语言的控制流都是至关重要的，更不用说 Rust 了。</p><h4 id="条件运算符" tabindex="-1">条件运算符 <a class="header-anchor" href="#条件运算符" aria-label="Permalink to “条件运算符”">​</a></h4><p>下表列出了所有常用的单个条件运算符：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">运算符</th><th style="text-align:left;">示例</th><th style="text-align:left;">解释</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&gt;</code></td><td style="text-align:left;"><code>a &gt; b</code></td><td style="text-align:left;"><code>a</code> <strong>大于</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>&lt;</code></td><td style="text-align:left;"><code>a &lt; b</code></td><td style="text-align:left;"><code>a</code> <strong>小于</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>==</code></td><td style="text-align:left;"><code>a == b</code></td><td style="text-align:left;"><code>a</code> <strong>等于</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>!=</code></td><td style="text-align:left;"><code>a != b</code></td><td style="text-align:left;"><code>a</code> <strong>不等于</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>&gt;=</code></td><td style="text-align:left;"><code>a &gt;= b</code></td><td style="text-align:left;"><code>a</code> <strong>大于</strong> 或 <strong>等于</strong> <code>b</code></td></tr><tr><td style="text-align:left;"><code>&lt;=</code></td><td style="text-align:left;"><code>a &lt;= b</code></td><td style="text-align:left;"><code>a</code> <strong>小于</strong> 或 <strong>等于</strong> <code>b</code></td></tr></tbody></table></div><p>以及下表是逻辑运算符，它们用于一个或多个条件之间：</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">运算符</th><th style="text-align:left;">示例</th><th style="text-align:left;">解释</th></tr></thead><tbody><tr><td style="text-align:left;">\`</td><td style="text-align:left;"></td><td style="text-align:left;">\` （逻辑或）</td></tr><tr><td style="text-align:left;"><code>&amp;&amp;</code> （逻辑与）</td><td style="text-align:left;"><code>条件1 &amp;&amp; 条件2</code></td><td style="text-align:left;"><strong>所有</strong> 条件都为 <code>true</code></td></tr><tr><td style="text-align:left;"><code>!</code> （逻辑非）</td><td style="text-align:left;"><code>!条件</code></td><td style="text-align:left;"><code>条件</code> 的布尔值的相反值</td></tr></tbody></table></div><blockquote><p>📋 与数学相似，你可以使用圆括号来指定操作的优先级。</p></blockquote><h3 id="使用-if-else" tabindex="-1">使用 if else <a class="header-anchor" href="#使用-if-else" aria-label="Permalink to “使用 if else”">​</a></h3><p>要控制 Rust 代码的基本流程，使用两个关键字：<code>if</code> 和 <code>else</code>。这可以根据提供的条件的状态创建两个“执行路径”。</p><p>一个简单的带有替代执行路径的 if 块的语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 条件 {</span></span>
<span class="line"><span>    &lt;语句&gt;;</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    &lt;语句&gt;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>📋 当只有一个条件时，将其括在圆括号中并不是强制性的。根据语法，使用圆括号是可选的。你仍然应该使用它们来指定优先级并优化可读性。</p></blockquote><p>来看看一个例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    let a = 36;</span></span>
<span class="line"><span>    let b = 25;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if a &gt; b {</span></span>
<span class="line"><span>        println!(&quot;a 大于 b&quot;);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        println!(&quot;b 大于 a&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里，我声明了两个整数变量 <code>a</code> 和 <code>b</code>，它们的值分别为 &#39;36&#39; 和 &#39;25&#39;。在第 5 行，我检查变量 <code>a</code> 中存储的值是否大于变量 <code>b</code> 中存储的值。如果条件计算结果为 <code>true</code>，则会执行第 6 行的代码。如果条件计算结果为 <code>false</code>，由于我们有一个 <code>else</code> 块（可选），第 8 行的代码将被执行。</p><p>来看看程序的输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a 大于 b</span></span></code></pre></div><p>完美！</p><p>来修改一下变量 <code>a</code> 的值，使其小于变量 <code>b</code> 的值，看看会发生什么。我将把 <code>a</code> 的值改为 &#39;10&#39;。修改后的输出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b 大于 a</span></span></code></pre></div><p>但是，如果我将相同的值存储在变量 <code>a</code> 和 <code>b</code> 中呢？为了看到这一点，我将两个变量的值都设置为 &#39;40&#39;。修改后的输出如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b 大于 a</span></span></code></pre></div><p>嗯？从逻辑上讲，这没有任何意义... 😦</p><p>但是这可以改进！我们继续。</p><h3 id="使用-else-if-条件" tabindex="-1">使用 else if 条件 <a class="header-anchor" href="#使用-else-if-条件" aria-label="Permalink to “使用 else if 条件”">​</a></h3><p>与其他任何编程语言一样，你可以使用 <code>else if</code> 块来提供多于两个的执行路径。语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 条件 {</span></span>
<span class="line"><span>    &lt;语句&gt;;</span></span>
<span class="line"><span>} else if 条件 {</span></span>
<span class="line"><span>    &lt;语句&gt;;</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    &lt;语句&gt;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在，通过使用 <code>else if</code> 块，我可以改进程序的逻辑。下面是修改后的程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    let a = 40;</span></span>
<span class="line"><span>    let b = 40;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if a == b {</span></span>
<span class="line"><span>        println!(&quot;a 与 b 是相等的&quot;);</span></span>
<span class="line"><span>    } else if a &gt; b {</span></span>
<span class="line"><span>        println!(&quot;a 大于 b&quot;);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        println!(&quot;b 大于 a&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在，我的程序的逻辑是正确的。它已经处理了所有的边缘情况（我能想到的）。第 5 行处理了 <code>a</code> 等于 <code>b</code> 的情况。第 7 行处理了 <code>a</code> 可能大于 <code>b</code> 的情况。而 <code>a</code> 小于 <code>b</code> 的情况则由第 9 行的 <code>else</code> 块隐式处理。</p><p>现在，当我运行这段代码时，我得到了以下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a 与 b 是相等的</span></span></code></pre></div><p>现在这就完美了！</p><h3 id="示例-找到最大值" tabindex="-1">示例：找到最大值 <a class="header-anchor" href="#示例-找到最大值" aria-label="Permalink to “示例：找到最大值”">​</a></h3><p>我知道使用 <code>if</code> 和 <code>else</code> 很容易，但是让我们再看一个程序。这次，我们来比较三个数字。我还将在这个实例中使用逻辑运算符！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    let a = 73;</span></span>
<span class="line"><span>    let b = 56;</span></span>
<span class="line"><span>    let c = 15;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (a != b) &amp;&amp; (a != c) &amp;&amp; (b != c) {</span></span>
<span class="line"><span>        if (a &gt; b) &amp;&amp; (a &gt; c) {</span></span>
<span class="line"><span>            println!(&quot;a 是最大的&quot;);</span></span>
<span class="line"><span>        } else if (b &gt; a) &amp;&amp; (b &gt; c) {</span></span>
<span class="line"><span>            println!(&quot;b 是最大的&quot;);</span></span>
<span class="line"><span>        } else {</span></span>
<span class="line"><span>            println!(&quot;c 是最大的&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个程序第一眼看上去可能很复杂，但是不要害怕，我会解释的！</p><p>最开始，我声明了三个变量 <code>a</code>、<code>b</code> 和 <code>c</code>，并赋予了我能想到的随机值。然后，在第 6 行，我检查了没有变量的值与其他变量相同的条件。首先，我检查 <code>a</code> 和 <code>b</code> 的值，然后是 <code>a</code> 和 <code>c</code>，最后是 <code>b</code> 和 <code>c</code>。这样我就可以确定没有变量中存储了重复的值。</p><p>然后，在第 7 行，我检查了变量 <code>a</code> 中存储的值是否是最大的。如果这个条件计算结果为 <code>true</code>，则会执行第 8 行的代码。否则，将检查第 9 行的执行路径。</p><p>在第 9 行，我检查了变量 <code>b</code> 中存储的值是否是最大的。如果这个条件计算结果为 <code>true</code>，则会执行第 10 行的代码。如果这个条件也是 <code>false</code>，那么只有一种可能。3 个变量中的最大值既不是 <code>a</code> 也不是 <code>b</code>。</p><p>所以，自然地，在 <code>else</code> 块中，我打印出变量 <code>c</code> 拥有最大值。</p><p>来看看程序的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a 是最大的</span></span></code></pre></div><p>这是预期的结果。尝试修改分配给每个变量的值，并自己测试一下！ 😃</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你学习到了如何使用 <code>if</code> 和 <code>else</code> 语句。在你继续使用大量 <code>if</code> <code>else if</code> 语句制作自己的 AI 之前（哈哈），让我们在本系列的下一篇文章中学习 Rust 中的循环。</p><p>持续关注。</p><p><em>（题图：MJ/3eea3bbb-b630-4470-ae21-391ab86cd5bf）</em></p><hr>`,52)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),n(a,{href:"https://itsfoss.com/rust-if-else/"},{default:l(()=>[...s[3]||(s[3]=[e("https://itsfoss.com/rust-if-else/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://itsfoss.com/author/pratham/"},{default:l(()=>[...s[5]||(s[5]=[e("Pratham Patel",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),n(a,{href:"https://github.com/lkxed/"},{default:l(()=>[...s[6]||(s[6]=[e("lkxed",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),n(a,{href:"https://github.com/Cubik65536"},{default:l(()=>[...s[7]||(s[7]=[e("Cubik65536",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const C=i(r,[["render",g]]);export{y as __pageData,C as default};
